/* =====================================================================
   PROYECTO FINAL - EJERCICIO SQL
   01) Crear la base y cargar los datos CRUDOS (tal como vienen en los CSV)
   Fuente: dataset "Ejemplo de Ex Final" del curso (Cliente, Productos,
           Sucursal, Vendedor, Ventas) - 5 archivos CSV separados por ";".
   Las tablas stg_ (staging) guardan todo como texto, sin corregir nada:
   asi queda evidencia de los problemas de calidad antes de limpiarlos.
   Autor: Leandro Jofre
   ===================================================================== */

IF DB_ID(N'ProyectoFinal_Jofre') IS NULL
    CREATE DATABASE ProyectoFinal_Jofre;
GO
USE ProyectoFinal_Jofre;
GO

DROP TABLE IF EXISTS dbo.stg_sucursal;
CREATE TABLE dbo.stg_sucursal (
    [ID_Sucursal] NVARCHAR(200) NULL,
    [Nombre suc] NVARCHAR(200) NULL,
    [Tamaño] NVARCHAR(200) NULL,
    [Zona] NVARCHAR(200) NULL
);
GO

GO

DROP TABLE IF EXISTS dbo.stg_vendedor;
CREATE TABLE dbo.stg_vendedor (
    [ID_Vendedor ] NVARCHAR(200) NULL,
    [Nombre completo] NVARCHAR(200) NULL,
    [Genero ] NVARCHAR(200) NULL,
    [Telefono ] NVARCHAR(200) NULL,
    [Estado Civil] NVARCHAR(200) NULL,
    [Contrato ] NVARCHAR(200) NULL,
    [id_Sucursal] NVARCHAR(200) NULL
);
GO

GO

DROP TABLE IF EXISTS dbo.stg_cliente;
CREATE TABLE dbo.stg_cliente (
    [id_Cliente] NVARCHAR(200) NULL,
    [DNI ] NVARCHAR(200) NULL,
    [Nombre completo ] NVARCHAR(200) NULL,
    [Número de contacto ] NVARCHAR(200) NULL,
    [Email ] NVARCHAR(200) NULL,
    [Género] NVARCHAR(200) NULL,
    [Ocupación] NVARCHAR(200) NULL,
    [Educación] NVARCHAR(200) NULL,
    [Descuento ] NVARCHAR(200) NULL,
    [Código cliente frecuente] NVARCHAR(200) NULL,
    [Nombre ] NVARCHAR(200) NULL
);
GO

GO

DROP TABLE IF EXISTS dbo.stg_productos;
CREATE TABLE dbo.stg_productos (
    [ID_Producto] NVARCHAR(200) NULL,
    [Producto] NVARCHAR(200) NULL,
    [Descripción Abreviada ] NVARCHAR(200) NULL,
    [Tamaño ] NVARCHAR(200) NULL,
    [Empaque ] NVARCHAR(200) NULL,
    [Embalaje] NVARCHAR(200) NULL,
    [Garantia ] NVARCHAR(200) NULL,
    [Peso Lb] NVARCHAR(200) NULL,
    [Dimensiones Cm] NVARCHAR(200) NULL
);
GO

GO

DROP TABLE IF EXISTS dbo.stg_ventas;
CREATE TABLE dbo.stg_ventas (
    [ID_Ventas] NVARCHAR(200) NULL,
    [ID_Producto] NVARCHAR(200) NULL,
    [ID_Cliente ] NVARCHAR(200) NULL,
    [ID_Ubicación] NVARCHAR(200) NULL,
    [ID_Codigo Pago ] NVARCHAR(200) NULL,
    [ID_Vendedor ] NVARCHAR(200) NULL,
    [Fecha compra] NVARCHAR(200) NULL,
    [Fecha Entrega] NVARCHAR(200) NULL,
    [Fecha Pago ] NVARCHAR(200) NULL,
    [Valor Unidad] NVARCHAR(200) NULL,
    [Cantidad ] NVARCHAR(200) NULL,
    [Costos Directos ] NVARCHAR(200) NULL,
    [Costos Indirectos ] NVARCHAR(200) NULL
);
GO

GO

GO

GO

GO

-- Control de la carga: filas por tabla (esperado: 6 / 108 / 400 / 96 / 1762)
SELECT 'stg_sucursal' AS tabla, COUNT(*) AS filas FROM dbo.stg_sucursal
UNION ALL SELECT 'stg_vendedor',  COUNT(*) FROM dbo.stg_vendedor
UNION ALL SELECT 'stg_cliente',   COUNT(*) FROM dbo.stg_cliente
UNION ALL SELECT 'stg_productos', COUNT(*) FROM dbo.stg_productos
UNION ALL SELECT 'stg_ventas',    COUNT(*) FROM dbo.stg_ventas;
